"use client";
/**
 * Real audio tones: the ringtone for an incoming call, the ringback you hear
 * while calling, the hang-up when a call ends, and the message tone. Ringing always plays (a call you can't
 * hear is a missed call); the message tone has its own switch in Settings.
 * Phones only let a page play sound after a tap, so the first tap anywhere
 * primes all three. Files are generated by scripts/synth-tones.py.
 */
type Tone = "ringtone" | "ringback" | "message" | "hangup";
const KEY = "clink_message_tone";
const els: Partial<Record<Tone, HTMLAudioElement>> = {};

function el(t: Tone): HTMLAudioElement | null {
  if (typeof window === "undefined") return null;
  if (!els[t]) {
    const a = new Audio(`/sounds/${t}.mp3`);
    a.preload = "auto";
    a.loop = t === "ringtone" || t === "ringback";
    a.volume = t === "ringback" ? 0.5 : t === "message" ? 0.7 : t === "hangup" ? 0.6 : 0.9;
    els[t] = a;
  }
  return els[t]!;
}

let primed = false;
/** Tones a real play has asked for; the unlock trick must leave these alone. */
const wanted = new Set<Tone>();
function play(t: Tone, a: HTMLAudioElement) {
  wanted.add(t);
  a.muted = false;
  a.currentTime = 0;
  void a
    .play()
    .catch(() => undefined)
    .finally(() => setTimeout(() => wanted.delete(t), 1500));
}
/** Call once at startup: the first user gesture unlocks audio for later. */
export function primeTones() {
  if (typeof window === "undefined" || primed) return;
  const unlock = () => {
    primed = true;
    for (const t of ["ringtone", "ringback", "message", "hangup"] as const) {
      const a = el(t);
      if (!a) continue;
      // Already asked to play by this same tap: leave it playing.
      if (wanted.has(t)) continue;
      a.muted = true;
      void a
        .play()
        .then(() => {
          // If a real play came in meanwhile, don't silence or stop it.
          if (!wanted.has(t)) {
            a.pause();
            a.currentTime = 0;
          }
          a.muted = false;
        })
        .catch(() => {
          a.muted = false;
        });
    }
    window.removeEventListener("pointerdown", unlock, true);
    window.removeEventListener("keydown", unlock, true);
  };
  window.addEventListener("pointerdown", unlock, true);
  window.addEventListener("keydown", unlock, true);
}

export function startTone(t: "ringtone" | "ringback") {
  stopTones();
  const a = el(t);
  if (!a) return;
  play(t, a);
}

export function stopTones() {
  for (const t of ["ringtone", "ringback"] as const) {
    const a = els[t];
    if (a) {
      a.pause();
      a.currentTime = 0;
    }
  }
}

export function messageToneOn(): boolean {
  try {
    return localStorage.getItem(KEY) !== "off";
  } catch {
    return true;
  }
}
export function setMessageTone(on: boolean) {
  try {
    localStorage.setItem(KEY, on ? "on" : "off");
  } catch {
    /* storage blocked */
  }
}

export function playMessageTone() {
  if (!messageToneOn()) return;
  const a = el("message");
  if (!a) return;
  play("message", a);
}

const HANGUP_KEY = "clink_hangup_tone";
export function hangupToneOn(): boolean {
  try {
    return localStorage.getItem(HANGUP_KEY) !== "off";
  } catch {
    return true;
  }
}
export function setHangupTone(on: boolean) {
  try {
    localStorage.setItem(HANGUP_KEY, on ? "on" : "off");
  } catch {
    /* storage blocked */
  }
}

/** Three soft falling notes when a call ends, so you know it's over (unless switched off). */
export function playHangupTone(force = false) {
  if (!force && !hangupToneOn()) return;
  const a = el("hangup");
  if (!a) return;
  play("hangup", a);
}

/** Settings preview: a few seconds of any tone, whatever the switches say. */
export function previewTone(t: Tone) {
  if (t === "message") {
    const a = el("message");
    if (!a) return;
    play("message", a);
    return;
  }
  if (t === "hangup") return playHangupTone(true);
  startTone(t);
  setTimeout(stopTones, 3500);
}
